#include <stddef.h>
#include <time.h>

/* Complete declarations from curl/curl.h and curl/curlbuild.h, authenticated
 * against this owner's DWARF. Kept local until the shared curl header is adopted.
 */
typedef long curl_off_t;

typedef enum {
  CURLFILETYPE_FILE = 0,
  CURLFILETYPE_DIRECTORY,
  CURLFILETYPE_SYMLINK,
  CURLFILETYPE_DEVICE_BLOCK,
  CURLFILETYPE_DEVICE_CHAR,
  CURLFILETYPE_NAMEDPIPE,
  CURLFILETYPE_SOCKET,
  CURLFILETYPE_DOOR, /* is possible only on Sun Solaris now */

  CURLFILETYPE_UNKNOWN /* should never occur */
} curlfiletype;

struct curl_fileinfo {
  char *filename;
  curlfiletype filetype;
  time_t time;
  unsigned int perm;
  int uid;
  int gid;
  curl_off_t size;
  long int hardlinks;

  struct {
    /* If some of these fields is not NULL, it is a pointer to b_data. */
    char *time;
    char *perm;
    char *user;
    char *group;
    char *target; /* pointer to the target filename of a symlink */
  } strings;

  unsigned int flags;

  /* used internally */
  char * b_data;
  size_t b_size;
  size_t b_used;
};

_Static_assert(sizeof(struct curl_fileinfo) == 0x80, "curl_fileinfo target size");
_Static_assert(offsetof(struct curl_fileinfo, b_data) == 0x68,
               "curl_fileinfo buffer offset");

/* The original free operations call this Nintendo allocator entry point. */
extern void Curl_SigloFree(void *pointer);

void Curl_fileinfo_dtor(void *user, void *element)
{
  struct curl_fileinfo *finfo = element;
  (void)user;
  if(!finfo)
    return;

  /* Original Curl_safefree(finfo->b_data), including its nulling store. */
  Curl_SigloFree(finfo->b_data);
  finfo->b_data = NULL;
  Curl_SigloFree(finfo);
}

